// The docs' pages as the build found them, and the sidebar the settings
// make of them in one language. Pure, so the pages and the build share it.
import type { Lang, SidebarItem } from './config';
import { localize, resolveHref } from './resolve';

/** A docs page by its slug as the first language serves it, as docs/quick-start; the docs' own index is docs. */
export interface DocMeta {
	slug: string;
	title: string;
	description?: string;
	/** Where an autogenerated group places it, from its frontmatter's sidebar.order; lower first. */
	order?: number;
	/** Its label in the sidebar, from sidebar.label; its title otherwise. */
	label?: string;
}

/** Each language's pages by slug. A page a language lacks is served in it with the first language's content. */
export type DocsIndex = Partial<Record<Lang, Record<string, DocMeta>>>;

export type SidebarEntry =
	| { type: 'link'; label: string; href: string; external: boolean; slug?: string }
	| { type: 'group'; label: string; collapsed: boolean; entries: SidebarEntry[] };

/** The page of a slug in a language, its own or the first language's. */
export function docIn(index: DocsIndex, slug: string, lang: Lang, first: Lang): DocMeta | undefined {
	return index[lang]?.[slug] ?? index[first]?.[slug];
}

/** Every slug the site serves, in every language: the first language's pages. */
export function slugsOf(index: DocsIndex, first: Lang): string[] {
	return Object.keys(index[first] ?? {});
}

const byOrder = (a: DocMeta, b: DocMeta) => (a.order ?? Infinity) - (b.order ?? Infinity) || a.slug.localeCompare(b.slug);

/**
 * The sidebar in a language. Without items, every page: the docs' index
 * first, then each folder's pages as a group named by the folder.
 */
export function resolveSidebar(items: SidebarItem[] | undefined, index: DocsIndex, lang: Lang, first: Lang, base: string): SidebarEntry[] {
	const pages = Object.values(index[first] ?? {});
	const page = (slug: string, label?: string): SidebarEntry => {
		const meta = docIn(index, slug, lang, first);
		if (!meta) throw new Error(`nsgo-website: the docs' sidebar names ${slug}, which has no page`);
		return { type: 'link', label: label ?? meta.label ?? meta.title, slug, ...resolveHref(`${slug}/`, lang, first, base) };
	};
	// The pages under a folder of the docs, its subfolders as groups.
	const folder = (dir: string, collapsed: boolean): SidebarEntry[] => {
		const prefix = dir ? `docs/${dir.replace(/^\/|\/$/g, '')}/` : 'docs/';
		const under = pages.filter((p) => p.slug.startsWith(prefix));
		const direct = under.filter((p) => !p.slug.slice(prefix.length).includes('/')).sort(byOrder);
		const subs = [...new Set(under.map((p) => p.slug.slice(prefix.length).split('/')).filter((parts) => parts.length > 1).map((parts) => parts[0]))].sort();
		return [
			...direct.map((p) => page(p.slug)),
			...subs.map((sub): SidebarEntry => ({ type: 'group', label: sub, collapsed, entries: folder(`${prefix.slice(5)}${sub}`, collapsed) })),
		];
	};
	if (!items) return [...(index[first]?.docs ? [page('docs')] : []), ...folder('', false)];
	const entry = (item: SidebarItem): SidebarEntry => {
		if (typeof item === 'string') return page(item.replace(/^\/|\/$/g, ''));
		const label = localize(item.label, lang, first);
		if ('slug' in item) return page(item.slug.replace(/^\/|\/$/g, ''), label);
		if ('link' in item) return { type: 'link', label, ...resolveHref(item.link, lang, first, base) };
		if ('items' in item) return { type: 'group', label, collapsed: item.collapsed ?? false, entries: item.items.map(entry) };
		const collapsed = item.collapsed ?? item.autogenerate.collapsed ?? false;
		return { type: 'group', label, collapsed, entries: folder(item.autogenerate.directory, collapsed) };
	};
	return items.map(entry);
}

/** The sidebar's pages in order, for each page's neighbours. */
export function pagesOf(entries: SidebarEntry[]): (SidebarEntry & { type: 'link' })[] {
	return entries.flatMap((e) => (e.type === 'group' ? pagesOf(e.entries) : e.slug ? [e] : []));
}
